insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g3_tech_v1'
from (values
('126.8.c.4',3,'A new kind of technology that is just being developed, like a new type of robot or smart glasses, is an...','["emerging technology", "plain pencil", "old tool", "rock"]'::jsonb,0,'Emerging technologies are new and developing.','original'),
('126.8.c.4',4,'Which is the best example of an emerging technology?','["a rock", "a newly invented learning robot", "a paper clip", "a wooden spoon"]'::jsonb,1,'Emerging means new.','original'),
('126.8.c.6',4,'A bar graph shows that more students pick pizza than tacos. You can infer that...','["nobody eats lunch", "tacos are banned", "pizza is more popular in this group", "everyone likes pizza"]'::jsonb,2,'A trend is read from graph data.','original'),
('126.8.c.6',4,'Looking at a line graph of temperatures that goes up each week shows a...','["mistake", "rest", "border", "trend"]'::jsonb,3,'Trends show direction.','original'),
('126.8.c.7',3,'Making a slide show of your class survey so other students can learn from it is using a digital tool to...','["inform an audience", "lose results", "hide results", "erase results"]'::jsonb,0,'Publishing results informs others.','original'),
('126.8.c.1.A',3,'A story problem about sharing 12 cookies among 4 friends can be broken into smaller...','["stories", "subproblems", "songs", "snacks"]'::jsonb,1,'Decompose into smaller parts.','original'),
('126.8.c.1.B',4,'3, 6, 9, 12 ... In this number pattern, each step adds...','["one", "two", "three", "four"]'::jsonb,2,'The rule is add 3.','original'),
('126.8.c.1.C',3,'Working with your team to write down each step of a project is developing a...','["snack", "game", "joke", "plan collaboratively"]'::jsonb,3,'Documented plans list steps.','original'),
('126.8.c.1.D',4,'Your code says: move forward, move forward, turn, but the robot misses the target. Finding and removing the error is...','["debugging", "deleting the robot", "stopping", "decorating"]'::jsonb,0,'Debug means fix errors.','original'),
('126.8.c.2.A',4,'In a game, ''lives = 3'' stores a number that can change. ''Lives'' is a...','["sentence", "variable", "noun", "rule"]'::jsonb,1,'Variables store data.','original'),
('126.8.c.2.A',4,'A program starts the score at 0 and adds 1 every time you win. The score changes, so it is stored in a...','["loop", "border", "variable", "picture"]'::jsonb,2,'Variables hold changing values.','original'),
('126.c.2.B',4,'A program uses ''repeat 4 times: move forward'' to draw a square side. The repeat block is a...','["comment", "variable", "bug", "loop"]'::jsonb,3,'Loops repeat.','original'),
('126.c.2.B',4,'A program that says ''if the sensor sees a wall, then turn'' uses a...','["conditional", "loop", "variable", "comment"]'::jsonb,0,'If-then is a conditional.','original'),
('126.8.c.3.A',4,'Thinking about how you learn and which strategies work for you is called...','["metaphor", "metacognition", "meter", "metal"]'::jsonb,1,'Metacognition is thinking about thinking.','original'),
('126.8.c.3.B',3,'Asking classmates and your teacher for feedback on your invention and improving it is part of a...','["recess", "snack", "design process", "nap"]'::jsonb,2,'Design uses feedback.','original'),
('126.8.c.5.A',3,'Which is numerical data?','["your favorite color", "a song name", "a story title", "the price of a pencil"]'::jsonb,3,'Prices are numbers.','original'),
('126.8.c.5.A',3,'Recording the temperature each hour is collecting...','["numerical data", "stories", "songs", "names"]'::jsonb,0,'Temperatures are numbers.','original'),
('126.8.c.5.B',3,'To get better results from a search, you can use specific...','["capital letters only", "keywords", "blank spaces", "emojis only"]'::jsonb,1,'Specific keywords help.','original'),
('126.8.c.8.A',3,'The trail of information you leave online, like posts and searches, is your digital...','["floor", "foot", "footprint", "font"]'::jsonb,2,'Digital footprints last.','original'),
('126.8.c.8.B',3,'Being polite and respectful when you communicate online is called digital...','["equation", "echo", "estimate", "etiquette"]'::jsonb,3,'Etiquette means good manners.','original'),
('126.8.c.8.C',3,'Working on the same online project with classmates is digital...','["collaboration", "isolation", "competition", "deletion"]'::jsonb,0,'Collaboration is shared work online.','original'),
('126.8.c.9.A',3,'Following the school''s acceptable use policy shows positive...','["bad habits", "social behavior online", "secrets", "silence"]'::jsonb,1,'AUPs guide good behavior.','original'),
('126.8.c.9.B',4,'Copyright law protects the work of...','["only the internet", "only the library", "the creator who made it", "nobody"]'::jsonb,2,'Creators own their work.','original'),
('126.8.c.9.B',4,'Which is an appropriate use of a picture you found online?','["removing the artist''s name", "copying it and saying you made it", "selling it as your own", "asking permission or using a free-to-use picture and giving credit"]'::jsonb,3,'Respect copyright.','original'),
('126.8.c.9.C',4,'A citation for an online picture should include the creator, the title and the...','["website or source", "lunch", "weather", "favorite color"]'::jsonb,0,'Citations list sources.','original'),
('126.8.c.10.A',3,'After using a school computer, you should always...','["leave your account open", "log out", "share your password", "turn up the volume"]'::jsonb,1,'Log out for security.','original'),
('126.8.c.10.B',4,'Which is a safe practice online?','["share your passwords", "click every link", "avoid clicking suspicious links", "open files from strangers"]'::jsonb,2,'Suspicious links can be harmful.','original'),
('126.8.c.10.B',4,'Protecting your digital identity means keeping personal details like your address...','["posted on every site", "shared with strangers", "public", "secret and protected"]'::jsonb,3,'Protect identifying info.','original'),
('126.8.c.10.C',3,'If someone sends you mean messages online, you should...','["tell a trusted adult", "delete the evidence only", "keep it a secret", "answer with meaner messages"]'::jsonb,0,'Report cyberbullying.','original'),
('126.8.c.11.A',4,'To write a report, the best tool is a...','["spreadsheet", "word processor", "presentation tool", "calculator only"]'::jsonb,1,'Word processors write text.','original'),
('126.8.c.11.A',4,'To organize and add up your class''s savings numbers in rows and columns, use a...','["presentation tool", "word processor", "spreadsheet", "paintbrush"]'::jsonb,2,'Spreadsheets handle numbers.','original'),
('126.8.c.11.A',4,'To show images and key points to the class, use a...','["word processor only", "ruler", "spreadsheet", "presentation tool"]'::jsonb,3,'Slides present ideas.','original'),
('126.8.c.11.B',3,'Changing how wide the white space is around the edges of your page changes the...','["margins", "link", "clip", "font"]'::jsonb,0,'Margins are page edges.','original'),
('126.8.c.11.B',3,'Adding a picture to your document is called...','["closing a file", "inserting an image", "hiding a page", "deleting an image"]'::jsonb,1,'Insert adds content.','original'),
('126.8.c.12.A',4,'A wireless network that lets devices connect to the internet without cables is a...','["stone network", "string network", "Wi-Fi network", "paper network"]'::jsonb,2,'Wi-Fi is wireless.','original'),
('126.8.c.12.A',4,'A private network used inside a school is called an...','["outernet", "kitchenet", "internet", "intranet"]'::jsonb,3,'An intranet is internal.','original'),
('126.8.c.12.B',3,'Naming a file ''Planets-Report'' instead of ''Doc1'' helps you...','["find it later", "lose it", "hide it", "break it"]'::jsonb,0,'Good file names help you find files.','original'),
('126.8.c.12.B',3,'Keeping files in organized folders is good file...','["noise", "management", "dancing", "decoration"]'::jsonb,1,'File management organizes.','original'),
('126.8.c.12.C',3,'Touch keyboarding means typing...','["with eyes closed only", "only with a mouse", "without looking at the keys", "only with one finger"]'::jsonb,2,'Touch typing uses muscle memory.','original'),
('126.8.c.12.D',4,'The shortcut to copy selected text on many computers is...','["Control and P", "Shift and Tab", "Control and Q", "Control (or Command) and C"]'::jsonb,3,'Copy is Ctrl+C.','original'),
('126.8.c.12.D',4,'Pressing Control (or Command) and Z does what?','["undoes your last action", "saves forever", "closes the program", "prints"]'::jsonb,0,'Z undoes.','original'),
('126.8.c.12.E',4,'Your app freezes. A simple first fix to try with help is to...','["throw the computer", "close it and reopen it", "pour water", "hit the keyboard"]'::jsonb,1,'Restarting is a basic fix.','original'),
('126.8.c.12.E',3,'If your computer will not connect to the internet, a minor problem might be that...','["the floor is cold", "the desk is brown", "Wi-Fi is turned off", "the sky is blue"]'::jsonb,2,'Check Wi-Fi.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Technology Applications' and d.language = 'en'
on conflict (fingerprint) do nothing;
